#if DEHERM_PROFILE_ENABLED
// Telemetry identity resolvers. A consumer draining the ring maps the numeric
// operation index and contract shape id back to their cold names through these.
extern "C" uint16_t deherm_script_universal_profile_contract_shape(uint32_t operationIndex) {
  return operationIndex < 915u ? kProfileContractShapes[operationIndex] : UINT16_C(0);
}
extern "C" const char* deherm_script_universal_profile_name(uint32_t operationIndex) {
  return operationIndex < 915u ? kProfileNames[operationIndex] : "deherm.typed-native.unknown";
}
extern "C" uint32_t deherm_script_universal_profile_contract_shape_count(void) { return 64u; }
extern "C" const char* deherm_script_universal_profile_contract_shape_name(uint16_t shapeId) {
  return shapeId < 64u ? kProfileContractShapeNames[shapeId] : "unknown";
}
#endif

extern "C" DehermScriptUniversalStatus deherm_script_universal_dispatch(
    uint32_t stable_id,
    const DehermScriptUniversalValue* input_values, uint32_t input_value_count,
    const DehermScriptUniversalEntry* input_entries, uint32_t input_entry_count,
    const char* input_strings, uint32_t input_string_bytes,
    const float* input_floats, uint32_t input_float_count,
    const DehermScriptUniversalUrl* input_urls, uint32_t input_url_count,
    const uint32_t* argument_roots, uint32_t argument_count,
    DehermScriptUniversalValue* output_values, uint32_t output_value_capacity,
    uint32_t* output_value_count,
    DehermScriptUniversalEntry* output_entries, uint32_t output_entry_capacity,
    uint32_t* output_entry_count,
    char* output_strings, uint32_t output_string_capacity,
    uint32_t* output_string_bytes,
    float* output_floats, uint32_t output_float_capacity,
    uint32_t* output_float_count,
    DehermScriptUniversalUrl* output_urls, uint32_t output_url_capacity,
    uint32_t* output_url_count,
    uint32_t* result_roots, uint32_t result_capacity,
    uint32_t* result_count,
    char* error, uint32_t error_capacity) {
  if (output_value_count) *output_value_count = 0;
  if (output_entry_count) *output_entry_count = 0;
  if (output_string_bytes) *output_string_bytes = 0;
  if (output_float_count) *output_float_count = 0;
  if (output_url_count) *output_url_count = 0;
  if (result_count) *result_count = 0;
  if (error && error_capacity) error[0] = '\0';
  const auto* operation = defold_hermes::universal_value::find(stable_id);
  if (!operation) return fail(DEHERM_SCRIPT_UNIVERSAL_ROUTE_MISSING, error, error_capacity, "Stable ID is not in the universal-value family");
  const size_t operationIndex = static_cast<size_t>(operation - defold_hermes::universal_value::operations());
  DEHERM_PROFILE_TRANSPORT_SCOPE(DEHERM_PROFILE_TRANSPORT_TYPED_NATIVE, stable_id,
      kProfileContractShapes[operationIndex], kProfileNames[operationIndex]);
  if (argument_count < operation->minimumArgumentCount || argument_count > operation->maximumArgumentCount ||
      argument_count > DEHERM_SCRIPT_UNIVERSAL_MAX_ARGUMENTS || (argument_count && !argument_roots) ||
      input_value_count > DEHERM_SCRIPT_UNIVERSAL_MAX_VALUES || (input_value_count && !input_values) ||
      input_entry_count > DEHERM_SCRIPT_UNIVERSAL_MAX_ENTRIES || (input_entry_count && !input_entries) ||
      input_string_bytes > DEHERM_SCRIPT_UNIVERSAL_MAX_STRING_BYTES || (input_string_bytes && !input_strings) ||
      input_float_count > DEHERM_SCRIPT_UNIVERSAL_MAX_MATRIX4_VALUES * 16u || (input_float_count && !input_floats) ||
      input_url_count > DEHERM_SCRIPT_UNIVERSAL_MAX_URL_VALUES || (input_url_count && !input_urls)) {
    return fail(DEHERM_SCRIPT_UNIVERSAL_INVALID_VALUE, error, error_capacity, "Universal input frame violates generated bounds");
  }
  if (!output_value_count || !output_entry_count || !output_string_bytes || !output_float_count || !output_url_count || !result_count ||
      output_value_capacity > DEHERM_SCRIPT_UNIVERSAL_MAX_VALUES || (output_value_capacity && !output_values) ||
      output_entry_capacity > DEHERM_SCRIPT_UNIVERSAL_MAX_ENTRIES || (output_entry_capacity && !output_entries) ||
      output_string_capacity > DEHERM_SCRIPT_UNIVERSAL_MAX_STRING_BYTES || (output_string_capacity && !output_strings) ||
      output_float_capacity > DEHERM_SCRIPT_UNIVERSAL_MAX_MATRIX4_VALUES * 16u || (output_float_capacity && !output_floats) ||
      output_url_capacity > DEHERM_SCRIPT_UNIVERSAL_MAX_URL_VALUES || (output_url_capacity && !output_urls) ||
      result_capacity < operation->maximumResultCount || (result_capacity && !result_roots)) {
    return fail(DEHERM_SCRIPT_UNIVERSAL_ARENA_EXHAUSTED, error, error_capacity, "Universal output frame violates generated bounds or capacity");
  }

  // The route's generated frame profile owns the stack scratch. Everything the
  // body needs is bundled so one dispatcher body serves every profile.
  const WireFrame wire{
      input_values, input_value_count, input_entries, input_entry_count,
      input_strings, input_string_bytes, input_floats, input_float_count,
      input_urls, input_url_count, argument_roots, argument_count,
      output_values, output_value_capacity, output_value_count,
      output_entries, output_entry_capacity, output_entry_count,
      output_strings, output_string_capacity, output_string_bytes,
      output_floats, output_float_capacity, output_float_count,
      output_urls, output_url_capacity, output_url_count,
      result_roots, result_count, error, error_capacity};
  return kContractFrames[kRouteContractFrames[operationIndex]](*operation, wire);
}

extern "C" void deherm_script_universal_release(DehermScriptUniversalValue* value) {
  if (!value) return;
  if (value->tag == static_cast<uint8_t>(ScriptValueTag::kHandle)) {
    const auto kind = static_cast<ScriptHandleKind>(value->handle_kind);
    if (kind == ScriptHandleKind::kGuiNode || kind == ScriptHandleKind::kLuaUserdata ||
        kind == ScriptHandleKind::kLuaSemanticHandle) {
      releaseScriptHandle(kind, value->runtime, value->payload);
    }
  }
  *value = {};
}
